mapper.select:
select
con.Con_Name as conName, con.Con_Code as conCode, con.Con_Money_Total as conMoneyTotal, con.Con_Pricing_Method as conPricingMethod, con.Con_Other_Valuation as conOtherValuation, con1.Con_Name as conAnnualName, con1.Con_Code as conAnnualCode, con1.Con_Pricing_Method as conAnnualPricingMethod, con1.Con_Other_Valuation as conAnnualOtherValuation, c1.C_Name as ctdCpyName, c1.C_Abbreviation as ctdCpyAbbName, c2.C_Name as ctdSoutCpyName, c2.C_Abbreviation as ctdSoutCpyAbbName, c3.C_Name as ctdQualityCpyName, c3.C_Abbreviation as ctdQualityCpyAbbName, mn.* from Con_Task_Delegation mn
left join Con_Contract con on mn.Con_Id=con.Con_Id left join Con_Contract con1 on mn.Con_Annual_Id=con1.Con_Id left join Sys_Company c1 on mn.Ctd_Cpy=c1.C_Id left join Sys_Company c2 on mn.Ctd_Sout_Cpy=c2.C_Id left join Sys_Company c3 on mn.Ctd_Quality_Cpy=c3.C_Id ${params.authSql}
and mn.Con_Id = #{params.conId}
and mn.Te_Id = #{params.teId}
and mn.P_Id=#{params.pId}
and mn.Ctd_Type=#{params.ctdType}
and mn.Ctd_Pro_Type=#{params.ctdProType}
and mn.State=#{params.state}
and INSTR(mn.Ctd_Code,#{params.ctdCode})
and INSTR(mn.Create_Uname,#{params.createUname})
and INSTR(mn.Ctd_Pro_No,#{params.ctdProNo})
and INSTR(mn.Ctd_Supervise_No,#{params.ctdSuperviseNo})
and INSTR(mn.Ctd_Contacts,#{params.ctdContacts})
and INSTR(mn.Ctd_Sout_Contacts,#{params.ctdSoutContacts})
and INSTR(mn.Ctd_Sampler,#{params.ctdSampler})
and INSTR(mn.Ctd_Witness,#{params.ctdWitness})
and likePname(#{params.pName},pro.P_Id)=true
and INSTR(pro.P_Name,#{params.pName})
and INSTR(con.Con_Name,#{params.conName})
and INSTR(con1.Con_Name,#{params.conAnnualName})
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Create_Time desc
